import{_ as e,o as i,c as o,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Expanded Settings Suggestion List","description":"","frontmatter":{},"headers":[],"relativePath":"en/98-扩展设定建议清单.md","filePath":"en/98-扩展设定建议清单.md"}'),a={name:"en/98-扩展设定建议清单.md"};function s(d,t,r,c,l,h){return i(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="expanded-settings-suggestion-list" tabindex="-1">Expanded Settings Suggestion List <a class="header-anchor" href="#expanded-settings-suggestion-list" aria-label="Permalink to &quot;Expanded Settings Suggestion List&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Document number</td><td>98</td></tr><tr><td>Module</td><td>Appendices and Reference Materials</td></tr><tr><td>Core keywords</td><td>expanded settings, creation suggestions, setting directions, openness, fields awaiting development</td></tr></tbody></table><h2 id="i-notes" tabindex="-1">I. Notes <a class="header-anchor" href="#i-notes" aria-label="Permalink to &quot;I. Notes&quot;">​</a></h2><p>This document lists the directions and suggestions available for expansion creation in the setting system of the Anchor Symbiotic Civilization, aiming to provide inspiration and guidance for setting creators and help them make valuable setting expansions within the existing framework. This list is classified by module; each expansion direction includes a description of the direction, the expansion value, the connection with existing settings, and creation suggestions. It should be emphasized that this list is only advisory; creators may give full play within the premise of maintaining setting consistency, and may also develop entirely new directions not covered by this list. All expanded settings must pass the check of Document 97 &quot;Setting Contradiction Self-Check List&quot; before being formally incorporated.</p><h2 id="ii-expansion-directions-of-the-worldview-and-core-settings" tabindex="-1">II. Expansion Directions of the Worldview and Core Settings <a class="header-anchor" href="#ii-expansion-directions-of-the-worldview-and-core-settings" aria-label="Permalink to &quot;II. Expansion Directions of the Worldview and Core Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Number</th><th>Expansion direction</th><th>Expansion value</th><th>Related settings</th><th>Creation suggestions</th></tr></thead><tbody><tr><td>E01</td><td>Existences beyond the boundary of the universe</td><td>Explore whether there are other universes or higher-dimensional existences beyond the law network of the Hengyuan Universe, providing a grander cosmology for the setting</td><td>Documents 00, 28</td><td>The existence of a &quot;cosmic wall&quot; can be set, along with the stories of a very few explorers who break through the cosmic wall, laying the groundwork for future cross-universe interaction</td></tr><tr><td>E02</td><td>The essence of the cosmic will</td><td>Deeply explore whether some &quot;cosmic will&quot; exists at the bottom of the law network, and its relationship with the anchor mechanism</td><td>Documents 00, 20</td><td>The cosmic will can be set as a non-personified self-organizing phenomenon of laws rather than a specific deity, maintaining the stance of &quot;Reality as the Foundation&quot;</td></tr><tr><td>E03</td><td>Lost civilizations of the pre-Anchor era</td><td>Set in detail the once-glorious but now-extinct civilizations of the pre-Anchor era, enriching historical depth</td><td>Documents 71, 93</td><td>Three to five representative lost civilizations can be set, each with its unique cultivation system, culture, and cause of extinction, providing material for archaeology settings</td></tr><tr><td>E04</td><td>Philosophical schools of the symbiosis concept</td><td>Within the grand framework of &quot;against predation, for symbiosis,&quot; set different philosophical schools&#39; different interpretations of the symbiosis concept</td><td>Documents 04, 03</td><td>Schools such as the &quot;radical symbiosis school,&quot; &quot;moderate symbiosis school,&quot; &quot;ecological symbiosis school,&quot; and &quot;technological symbiosis school&quot; can be set; their intellectual confrontations can become important dramatic tension</td></tr></tbody></table><h2 id="iii-expansion-directions-of-the-cultivation-system" tabindex="-1">III. Expansion Directions of the Cultivation System <a class="header-anchor" href="#iii-expansion-directions-of-the-cultivation-system" aria-label="Permalink to &quot;III. Expansion Directions of the Cultivation System&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Number</th><th>Expansion direction</th><th>Expansion value</th><th>Related settings</th><th>Creation suggestions</th></tr></thead><tbody><tr><td>E05</td><td>Detailed techniques of a single system</td><td>Elaborate on one of the Three Hundred Systems, including specific cultivation techniques, realm breakthrough methods, and common misconceptions</td><td>Documents 10–19, 91</td><td>It is suggested to prioritize the Three Origin Foundations and the systems of the Applied Engineering category closely integrated with technology; each system&#39;s detailed document may include cultivation steps, mantra formulas, resource requirements, and risk warnings</td></tr><tr><td>E06</td><td>Combination schemes of concurrent cultivation</td><td>Study the compatibility of concurrent cultivation among different systems and design optimal multi-system combination schemes</td><td>Documents 10, 11–13</td><td>&quot;Golden combinations&quot; (such as Deduction Iteration + Spatial Legal Principle + Applied Engineering) and various offbeat combinations can be set, analyzing the advantages and limitations of each combination</td></tr><tr><td>E07</td><td>Cultivation bottlenecks and breakthrough methods</td><td>Set in detail the bottlenecks that each system may encounter at different realms, and the multiple methods for breaking through them</td><td>Documents 14, 19</td><td>Different types of bottlenecks such as the &quot;heart-demon tribulation,&quot; &quot;law barrier,&quot; and &quot;origin obstacle&quot; can be set, along with corresponding breakthrough paths, adding depth to the cultivation process</td></tr><tr><td>E08</td><td>Special constitutions and system adaptation</td><td>Set various special constitutions (such as the innate Dao body, elemental affinity body, and strong consciousness sensor) and their adaptation relationships with different cultivation systems</td><td>Documents 12, 51</td><td>A &quot;constitution–system adaptation matrix&quot; can be designed to help creators quickly determine which systems a certain constitution is suitable for cultivating</td></tr><tr><td>E09</td><td>Detailed classification of cultivation resources</td><td>Classify and set in detail the various resources needed for cultivation (heavenly materials and earthly treasures, energy crystals, law fragments, etc.)</td><td>Documents 18, 65</td><td>The grade, place of origin, collection method, preservation method, and usage taboos of resources can be set, constructing a complete cultivation resource ecology</td></tr></tbody></table><h2 id="iv-expansion-directions-of-the-social-system" tabindex="-1">IV. Expansion Directions of the Social System <a class="header-anchor" href="#iv-expansion-directions-of-the-social-system" aria-label="Permalink to &quot;IV. Expansion Directions of the Social System&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Number</th><th>Expansion direction</th><th>Expansion value</th><th>Related settings</th><th>Creation suggestions</th></tr></thead><tbody><tr><td>E10</td><td>Specific social forms of the Five Typologies</td><td>Elaborate on the specific social systems, economic models, and cultural characteristics of each of the Five Symbiotic Civilization Typologies</td><td>Documents 30–35</td><td>Each typology can have its typical urban form, family structure, education model, and festivals set, making the Five Typologies each distinctive</td></tr><tr><td>E11</td><td>Planning and construction of symbiotic cities</td><td>Set the planning concepts, architectural styles, infrastructure, and functional zoning of cities in the symbiotic civilization</td><td>Documents 39, 60</td><td>Different types of urban forms such as &quot;vertical symbiotic city,&quot; &quot;ecologically nested city,&quot; and &quot;space-folding city&quot; can be designed</td></tr><tr><td>E12</td><td>Detailed operation of the education system</td><td>Set in detail the complete operation mechanism of the symbiotic education system, from preschool education to higher education and cultivation education</td><td>Documents 37, 43</td><td>The curriculum system, assessment methods, mentor system, and cross-racial education plans can be set</td></tr><tr><td>E13</td><td>Detailed operation of the medical system</td><td>Set in detail the operation mechanism of the symbiotic medical system, including the combination of conventional medical care and cultivation medical care</td><td>Documents 38, 44</td><td>The hospital system, medical insurance reimbursement procedures, special norms for cultivation treatment, and cross-racial medical plans can be set</td></tr><tr><td>E14</td><td>Social security and welfare system</td><td>Set in detail the social security system of the symbiotic civilization, including elderly care, unemployment, and relief</td><td>Documents 32, 08</td><td>The application conditions, distribution standards, funding sources, and supervision mechanisms of benefits can be set</td></tr></tbody></table><h2 id="v-expansion-directions-of-law-and-governance" tabindex="-1">V. Expansion Directions of Law and Governance <a class="header-anchor" href="#v-expansion-directions-of-law-and-governance" aria-label="Permalink to &quot;V. Expansion Directions of Law and Governance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Number</th><th>Expansion direction</th><th>Expansion value</th><th>Related settings</th><th>Creation suggestions</th></tr></thead><tbody><tr><td>E15</td><td>Typical legal cases</td><td>Write typical cases tried by the Symbiotic Court, demonstrating the application of law in practice</td><td>Documents 40–49, 92</td><td>Representative cases such as the &quot;cultivation resource monopoly case,&quot; &quot;cross-plane pollution compensation case,&quot; and &quot;Dark Replacement Entity rights case&quot; can be written</td></tr><tr><td>E16</td><td>Local autonomy system</td><td>Set in detail the autonomy systems and authority division of each star region and each plane within the constitutional framework</td><td>Documents 40, 49</td><td>The autonomy models of different autonomous units, their relationships with the central government, and the procedures for enacting autonomy regulations can be set</td></tr><tr><td>E17</td><td>Electoral and democratic systems</td><td>Set in detail the electoral system of the Anchor Assembly representatives and the democratic decision-making mechanism</td><td>Documents 32, 49</td><td>The division of constituencies, candidate qualifications, electoral procedures, voting methods, and term systems can be set</td></tr><tr><td>E18</td><td>Legal enforcement mechanism</td><td>Set in detail the enforcement mechanism of law, including law enforcement agencies, enforcement procedures, and compulsory measures</td><td>Documents 48, 49</td><td>The organizational structure, enforcement authority, enforcement procedures, and supervision mechanisms of law enforcement agencies can be set</td></tr></tbody></table><h2 id="vi-expansion-directions-of-life-and-races" tabindex="-1">VI. Expansion Directions of Life and Races <a class="header-anchor" href="#vi-expansion-directions-of-life-and-races" aria-label="Permalink to &quot;VI. Expansion Directions of Life and Races&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Number</th><th>Expansion direction</th><th>Expansion value</th><th>Related settings</th><th>Creation suggestions</th></tr></thead><tbody><tr><td>E19</td><td>Detailed settings of a single race</td><td>Elaborate on a certain race in the Register of the Ten Thousand Races, including physiological characteristics, social structure, cultural traditions, and historical evolution</td><td>Documents 50–52, 94</td><td>It is suggested to prioritize distinctive races such as the Dragon Race (Lóng Zú), Elf Race (Jīnglíng Zú), Machine Race (Jīxiè Zú), and Consciousness Body Race (Yìshítǐ Zú); each race may include language, religion, art, and customs</td></tr><tr><td>E20</td><td>Specific cases of Anomalous Life</td><td>Set specific Anomalous Life individuals or groups, demonstrating the practical application of the three types of handling procedures</td><td>Documents 53–54</td><td>Cases such as &quot;void drifters,&quot; &quot;time-fragment life,&quot; and &quot;law parasites&quot; can be set</td></tr><tr><td>E21</td><td>Specific types of Anomalous Energy</td><td>Set in detail the characteristics, sources, uses, and control methods of various Anomalous Energies</td><td>Documents 55–56</td><td>Types such as &quot;causal energy,&quot; &quot;consciousness energy,&quot; and &quot;time-echo energy&quot; can be set</td></tr><tr><td>E22</td><td>Specific cases of Dark Replacement Entities</td><td>Set specific individual stories of Dark Replacement Entities, demonstrating the practical application of the Dual-Soul Ethics and the handling of the four branches</td><td>Documents 57–59</td><td>Case stories of different types of Dark Replacement Entities can be written, exploring the ethical dilemmas of dual-soul coexistence</td></tr><tr><td>E23</td><td>Offspring of cross-racial integration</td><td>Set the characteristics and culture of mixed races born from intermarriage between different races</td><td>Documents 52, 77</td><td>Mixed races such as &quot;half-elves,&quot; &quot;dragon-kin,&quot; and &quot;mechanical bionic humans&quot; can be set, exploring their identity and cultural fusion</td></tr></tbody></table><h2 id="vii-expansion-directions-of-technology-and-energy" tabindex="-1">VII. Expansion Directions of Technology and Energy <a class="header-anchor" href="#vii-expansion-directions-of-technology-and-energy" aria-label="Permalink to &quot;VII. Expansion Directions of Technology and Energy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Number</th><th>Expansion direction</th><th>Expansion value</th><th>Related settings</th><th>Creation suggestions</th></tr></thead><tbody><tr><td>E24</td><td>Detailed principles of a single technology</td><td>Provide a detailed analysis of the principles of a key technology (such as the Replication Mirror, isolated space, and the engineering of the Multiplying Fruit)</td><td>Documents 60–69, 63–64</td><td>The development history, core components, workflow, technical limitations, and upgrade directions of the technology can be set</td></tr><tr><td>E25</td><td>Detailed classification of cultivation equipment</td><td>Set the classification, functions, grades, and usage methods of various cultivation auxiliary equipment</td><td>Documents 61, 67</td><td>Equipment types such as &quot;cultivation pod,&quot; &quot;law detector,&quot; &quot;energy converter,&quot; and &quot;consciousness amplifier&quot; can be set</td></tr><tr><td>E26</td><td>Detailed settings of anchor hardware</td><td>Set in detail the structure, functions, construction, and maintenance of anchor hardware facilities</td><td>Documents 20, 67</td><td>The core components, energy supply, maintenance cycle, and fault handling of artificial anchors can be set</td></tr><tr><td>E27</td><td>Cross-plane communication technology</td><td>Set in detail the technical principles, equipment types, communication protocols, and security mechanisms of cross-plane communication</td><td>Documents 66, 81</td><td>Different communication methods such as &quot;anchor-wave communication,&quot; &quot;space-folding communication,&quot; and &quot;consciousness resonance communication&quot; can be set</td></tr></tbody></table><h2 id="viii-expansion-directions-of-history-and-events" tabindex="-1">VIII. Expansion Directions of History and Events <a class="header-anchor" href="#viii-expansion-directions-of-history-and-events" aria-label="Permalink to &quot;VIII. Expansion Directions of History and Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Number</th><th>Expansion direction</th><th>Expansion value</th><th>Related settings</th><th>Creation suggestions</th></tr></thead><tbody><tr><td>E28</td><td>Detailed accounts of major historical events</td><td>Provide detailed historical accounts of a major event in the chronology</td><td>Documents 70–79, 93</td><td>The full process of events such as the &quot;opening event of the Three Hundred Systems,&quot; &quot;implementation of the 20% Activation Strategy,&quot; and &quot;the first ascension milestone&quot; can be recounted in detail</td></tr><tr><td>E29</td><td>Biographies of historical figures</td><td>Write detailed biographies for key figures, enriching the humanistic depth of history</td><td>Document 95</td><td>Biographies can be written for key figures such as &quot;Xuánhéng Zǐ,&quot; &quot;Gòngshēng Zǐ,&quot; &quot;Lìxiàn Gōng,&quot; and &quot;Sānbǎi Shī&quot;</td></tr><tr><td>E30</td><td>Hypothetical analysis of historical turning points</td><td>Analyze how the development of the symbiotic civilization would differ if a certain historical event had taken a different course</td><td>Documents 70–79</td><td>Hypothetical analyses such as &quot;what if the Symbiotic Constitution had not been passed&quot; and &quot;what if the 20% Activation Strategy had failed&quot; can be made, showing the contingency of history</td></tr><tr><td>E31</td><td>Detailed records of archaeological discoveries</td><td>Set the detailed discoveries and research results of a certain cross-plane archaeology</td><td>Documents 84–87</td><td>&quot;The archaeological discovery of a certain lost civilization&quot; and &quot;the time-regression archaeology results of a certain key historical node&quot; can be set</td></tr></tbody></table><h2 id="ix-expansion-directions-of-cross-plane-and-time" tabindex="-1">IX. Expansion Directions of Cross-Plane and Time <a class="header-anchor" href="#ix-expansion-directions-of-cross-plane-and-time" aria-label="Permalink to &quot;IX. Expansion Directions of Cross-Plane and Time&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Number</th><th>Expansion direction</th><th>Expansion value</th><th>Related settings</th><th>Creation suggestions</th></tr></thead><tbody><tr><td>E32</td><td>Detailed settings of specific planes</td><td>Set the law parameters, civilization forms, geographical environments, and histories of a specific plane</td><td>Documents 80, 81</td><td>Different types of specific planes such as the &quot;high-magic plane,&quot; &quot;technological plane,&quot; &quot;primordial plane,&quot; and &quot;consciousness plane&quot; can be set</td></tr><tr><td>E33</td><td>Cross-plane diplomacy cases</td><td>Set specific cases of the symbiotic civilization establishing diplomatic relations with other plane civilizations</td><td>Documents 81, 88</td><td>Specific diplomatic events such as first contact, establishment-of-relations negotiations, cultural exchange, and trade agreements can be set</td></tr><tr><td>E34</td><td>Specific cases of time regression</td><td>Set the specific process, discoveries, and impacts of a certain time regression operation</td><td>Documents 82–83, 89</td><td>Cases such as &quot;the regression-based resolution of a certain historical mystery&quot; and &quot;the regression-based restoration of a certain extinct civilization&quot; can be set</td></tr><tr><td>E35</td><td>Detailed records of time paradox events</td><td>Set the full process of a certain time paradox event, including its occurrence, emergency response, and causal repair</td><td>Document 89</td><td>A complete handling record of a small-scale paradox event can be written, demonstrating the practical operation of the prevention and control mechanisms</td></tr><tr><td>E36</td><td>Cross-plane conflicts and their resolution</td><td>Set conflicts between the symbiotic civilization and other plane civilizations and the peaceful resolution process</td><td>Documents 81, 88</td><td>Different types of cross-plane conflict cases such as resource disputes, cultural conflicts, and border disputes can be set</td></tr></tbody></table><h2 id="x-creation-principles-of-expanded-settings" tabindex="-1">X. Creation Principles of Expanded Settings <a class="header-anchor" href="#x-creation-principles-of-expanded-settings" aria-label="Permalink to &quot;X. Creation Principles of Expanded Settings&quot;">​</a></h2><p>When creating expanded settings, the following principles should be followed:</p><ol><li><strong>Consistency first</strong>: All expanded settings must remain logically consistent with existing settings and pass the check of the Setting Contradiction Self-Check List.</li><li><strong>Reality as the Foundation</strong>: Expanded settings should be reasonably deduced based on objective laws, avoiding pure fantasy and the collapse of settings.</li><li><strong>Symbiotic stance</strong>: Expanded settings should always uphold the core stance of opposing predation and advocating symbiosis, and must not defend predatory behavior.</li><li><strong>Openness</strong>: Expanded settings should maintain a certain degree of openness, leaving room for further expansion in the future.</li><li><strong>Practicality</strong>: Expanded settings should have practical creative value, providing useful material for story creation, game design, and theoretical discussion.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The Expanded Settings Suggestion List is the &quot;open door&quot; of the setting system of the Anchor Symbiotic Civilization. It shows that this setting system is not a closed, completed product, but a living system that continuously grows and enriches. The thirty-six expansion directions are only a starting point; the true creativity of settings comes from the imagination and enthusiasm of every participant. As long as the basic principle of setting consistency is followed, every valuable expansion will become an indispensable component of the grand narrative of the Anchor Symbiotic Civilization.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>97-设定矛盾自查表 (Setting Contradiction Self-Check List)</li><li>99-文档版本与维护说明 (Document Version and Maintenance Notes)</li><li>96-常见问题FAQ (Frequently Asked Questions (FAQ))</li></ul>',27)])])}const p=e(a,[["render",s]]);export{m as __pageData,p as default};
